code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    marked = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    # Fill gaps between marked cells along each row and column.
    for r in range(h):
        cols = [c for rr, c in marked if rr == r]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r, cc in marked if cc == c]
        if len(rows) >= 2:
            for r in range(min(rows) + 1, max(rows)):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
'''
